function Addition()
{
var a, b, c, d, e, g, h, coi, cop, i, j;
        a=Number(document.getElementById("BA").value);
        b=Number(document.getElementById("AA").value);
        c=Number(document.getElementById("PA").value);
        d=Number(document.getElementById("PTR").value);
        e=Number(document.getElementById("ADJ").value);
coi=Number(document.getElementById("COINS").value);
cop=Number(document.getElementById("COPAY").value);
if(a=="" || a==0 || b=="" || b==0 || c=="" || c==0 )
        {
window.alert("Please enter values in the all required fields");
}
else
{
if(a<b)
{
window.alert("Allowed amount cannot be greater than billed amount");
}
else
{
i = a-b;
if(i==e)
{
h=c+d+coi+cop;
        if(h==b)
{
document.getElementById("ERR").innerHTML="Payment Information is Correct";
}
else
{
document.getElementById("ERR").innerHTML="Error: The sum of paid amount & PTR must be equal to allowed amount";
}
g=a-((c+d+coi+cop)+e)
        document.getElementById("BAL").value=g;
}
else
{
document.getElementById("ADJ").value=i;
h=c+d+coi+cop;
        if(h==b)
{
document.getElementById("ERR").innerHTML="Payment Information is Correct";
}
else
{
document.getElementById("ERR").innerHTML="Error: The sum of paid amount & PTR must be equal to allowed amount";
}
j=a-((c+d+coi+cop)+i)
        document.getElementById("BAL").value=j;


}
}
}
}

