function calculateAR() {

var charges = document.getElementById("charges").value;
var ar = document.getElementById("ar").value;
var days = document.getElementById("days").value;

if(charges=="" || ar=="" || days==""){
alert("Please enter all fields");
return;
}

var avgDailyCharges = charges / days;
var arDays = ar / avgDailyCharges;

arDays = Math.round(arDays);

var priority = "";
var reason = "";
var action = "";

if(arDays <= 40){
priority = "Low";
reason = "AR days are within healthy industry benchmark.";
action = "Continue monitoring and maintain current billing and follow-up processes.";
}
else if(arDays <= 50){
priority = "Medium";
reason = "AR days are slightly higher than ideal range.";
action = "Review claim follow-ups and monitor aging buckets regularly.";
}
else if(arDays <= 60){
priority = "High";
reason = "Collections may be delayed or follow-ups may not be timely.";
action = "Improve denial management and increase follow-up on 30+ day claims.";
}
else{
priority = "Critical";
reason = "AR days are significantly high which may impact revenue cycle performance.";
action = "Immediate review of billing workflow, payer delays, and aging AR accounts is recommended.";
}

document.getElementById("resultBox").style.display="block";
document.getElementById("arDays").innerHTML="Days in AR: " + arDays;
document.getElementById("priority").innerHTML=priority;
document.getElementById("reason").innerHTML=reason;
document.getElementById("action").innerHTML=action;

}

